Translate the following GNU C++14 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++14 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
using ull = unsigned long long;

const ull INF = 17446744073709551616ull;
ull MOD, N, K;
ull dp[19][300005];
ull fact[300005], invfact[300005];

inline ull mod_pow(ull base, ull exp) {
    ull result = 1;
    while (exp) {
        if (exp & 1ULL) result = (result * base) % MOD;
        base = (base * base) % MOD;
        exp >>= 1ULL;
    }
    return result;
}

inline ull nCr(int a, int b) {
    return (((fact[a] * invfact[b]) % MOD) * invfact[a - b]) % MOD;
}

ull solve_even_case() {
    int limit = (int)max(N, K);
    fact[0] = 1ULL;
    for (int i = 1; i <= limit; ++i) fact[i] = fact[i - 1] * (ull)i % MOD;
    invfact[limit] = mod_pow(fact[limit], MOD - 2ULL);
    for (int i = limit - 1; i >= 0; --i) invfact[i] = invfact[i + 1] * (ull)(i + 1) % MOD;

    for (int i = 1; i <= (int)N; ++i) dp[1][i] = invfact[i];

    ull ans = dp[1][(int)N] * nCr((int)K, 1) % MOD;
    int maxLayer = min(18, (int)K);

    for (int i = 2; i <= maxLayer; ++i) {
        for (int j = (int)N; j > 0; j = (j - 1) & (int)N) {
            if (dp[i - 1][j] == 0) continue;
            int rest = (int)N ^ j;
            for (int l = rest; l > j; l = (l - 1) & rest) {
                dp[i][j ^ l] += dp[i - 1][j] * invfact[l];
                if (dp[i][j ^ l] > INF) dp[i][j ^ l] %= MOD;
            }
        }
        for (int j = (int)N; j > 0; j = (j - 1) & (int)N) {
            if (dp[i][j] >= MOD) dp[i][j] %= MOD;
        }
        ull res = dp[i][(int)N] * nCr((int)K, i) % MOD;
        res = res * fact[i] % MOD;
        ans = (ans + res >= MOD) ? ans + res - MOD : ans + res;
    }

    ans = ans * fact[(int)N] % MOD;
    return ans;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> K >> MOD;
    ull ans = mod_pow(K, N);
    if (N % 2ULL == 0ULL) ans = (ans - solve_even_case() + MOD) % MOD;
    cout << ans << '\n';
    return 0;
}
</original_code>
